'use strict'

function helper(text) {
  return '[util] ' + text
}

function compute(n) {
  return n * 2
}

function greet(name) {
  return 'hello, ' + name
}

class ChatService {
  constructor(prefix = '[chat]') {
    this.prefix = prefix
  }

  send(text) {
    return this._send(text)
  }

  _send(text) {
    return `${this.prefix} ${text}`
  }
}

module.exports = { helper, compute, greet, ChatService }
